
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_hjs_b88_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_hjs_b88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.206207201867274e+00, -4.123766166784913e+00, -4.008309247781292e+00, -3.848504352636471e+00, -3.631026316616365e+00, -3.342161942566955e+00, -2.971593973296620e+00, -2.519244196979137e+00, -2.004711926295331e+00, -1.472738491873871e+00, -9.745489527165629e-01, -6.378092064071400e-01, -5.386430957714782e-01, -4.327266750111092e-01, -2.967849760016467e-01, -1.703777781239236e-01, -8.110301421833237e-02, -3.037627906085063e-02, -2.345640672346135e-02, 0.000000000000000e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


